recipes.code:
{
  "inputs": [
    {
      "id": "madtaco-api-key",
      "type": "promptString",
      "description": "X-Api-Key for paid checks, usage, and proposals (free tools work without it)",
      "password": true
    }
  ],
  "servers": {
    "mcp": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "@madtaco/mcp@1.1.0"
      ],
      "env": {
        "MADTACO_API_BASE": "<madtaco-api-base>",
        "MADTACO_API_KEY": "${input:madtaco-api-key}"
      }
    }
  }
}
